def extract_pattern(output, r0, c0, scale=3):
    """Extract 3x3 pattern from output starting at (r0, c0)"""
    pattern = []
    for i in range(scale):
        row = []
        for j in range(scale):
            row.append(output[r0*scale + i][c0*scale + j])
        pattern.append(row)
    return pattern

